: "和定最值方向搞反"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忽略整数约束"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "最值问题是高频考点。最不利原则几乎每年必考，必须熟练掌握。"}]}]}]}$$ AS jsonb), NULL, '数量关系-最值问题-基础最值的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "最值问题", "基础最值"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ext_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
